/bin/bash -lc "set -e
for spec in \\
  'bing|https://www.bing.com/search?q=%22Government+Degree+College%2C+Haripur+Nihastha%22' \\
  'google|https://www.google.com/search?q=%22Government+Degree+College%2C+Haripur+Nihastha%22' \\
  'ddg|https://html.duckduckgo.com/html/?q=%22Government+Degree+College%2C+Haripur+Nihastha%22'; do
  name="'${spec%%|*}; url=${spec#*|}; out="$TMPDIR/haripur_${name}.html";
  echo "=== $name ===";
  if ! curl -L --fail --silent --show-error --max-time 30 -A '"'Mozilla/5.0' \""'$url" -o "$out" 2>"$TMPDIR/${name}.err"; then
    echo "normal_tls_failed: $(tr '"'\\n' ' ' < \""'$TMPDIR/${name}.err")";
    curl --insecure -L --fail --silent --show-error --max-time 30 -A '"'Mozilla/5.0' \""'$url" -o "$out";
  fi
  rg -oi '"'https?://["'^"<> ]+|<h[234][''^>]*>[''^<]+'"' \""'$out" | sed '"'s/&amp;/\\&/g' | head -40 || true
done"

