/bin/bash -lc "set -u
for q in '%haripur%' '%nihastha%' '%raebareli%'; do
  out=\""'$TMPDIR/haripur_crt_${q//%/_}.json"; err="$out.err"; url="https://crt.sh/?q=$q&output=json";
  echo "=== $url ==="
  if ! curl -L --fail --silent --show-error --max-time 30 "$url" -o "$out" 2>"$err"; then
    msg=$(tr '"'\\n' ' ' < \""'$err"); echo "normal_tls_failed: $msg"; 
    if printf '"'%s' \""'$msg" | rg -q '"'self signed certificate in certificate chain'; then curl --insecure -L --fail --silent --show-error --max-time 30 \""'$url" -o "$out" || true; fi
  fi
  [ -f "$out" ] && python3 - "$out" <<'"'PY'
import json,sys
from pathlib import Path
try:
 d=json.loads(Path(sys.argv[1]).read_text())
 names=set()
 for x in d:
  for n in x.get('name_value','').splitlines(): names.add(n.strip())
 print('\\n'.join(sorted(names))[:5000])
except Exception as e: print('parse_error',e)
PY
done"

